{"draft_implementation":{"solution.py":"def file_suffix(name: str) -> str:
    if '.' not in name or name.endswith('.') or name.startswith('.') or name.endswith(''):
        return ""
    parts = name.split('.')
    if len(parts) == 2 and not name.startswith('.') and '.' not in name[parts[0]]:
        return parts[1]
    if len(parts) == 1:
        return ""
    if parts[0] == '' and len(parts) > 1:
        return ""
    return parts[-1]
